Add-Type @'
using System;
using System.Runtime.InteropServices;
public static class Win32PopupProbe { [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd); }
'@; $taskName='Vault Timeline Materializer'; $seen=@{}; Start-ScheduledTask -TaskName $taskName; $started=$false; for($i=0;$i -lt 600;$i++){ $state=(Get-ScheduledTask -TaskName $taskName).State; if($state -eq 'Running'){$started=$true}; foreach($p in @(Get-CimInstance Win32_Process | Where-Object { $_.Name -in @('git.exe','gh.exe') })){ if($seen.ContainsKey($p.ProcessId)){continue}; $parent=Get-CimInstance Win32_Process -Filter "ProcessId=$($p.ParentProcessId)" -ErrorAction SilentlyContinue; if($parent -and (($parent.ExecutablePath -like '*\pythonw.exe') -or ($parent.CommandLine -match 'timeline_materializer\.py'))){ $gp=Get-Process -Id $p.ProcessId -ErrorAction SilentlyContinue; if($gp){$h=[intptr]$gp.MainWindowHandle; $vis=if($h -ne [intptr]::Zero){[Win32PopupProbe]::IsWindowVisible($h)}else{$false}; $seen[$p.ProcessId]=[pscustomobject]@{Name=$p.Name;Id=$p.ProcessId;MainWindowHandle=$gp.MainWindowHandle;Visible=$vis;Title=$gp.MainWindowTitle;CommandLine=$p.CommandLine} } } }; if($started -and $state -eq 'Ready'){break}; Start-Sleep -Milliseconds 40 }; $info=Get-ScheduledTaskInfo -TaskName $taskName; [pscustomobject]@{State=(Get-ScheduledTask -TaskName $taskName).State;LastRunTime=$info.LastRunTime;LastTaskResult=$info.LastTaskResult} | Format-List; Write-Output 'ATTRIBUTED_TIMELINE_CHILDREN'; $seen.Values | Sort-Object Visible -Descending,Name,Id | Format-Table -AutoSize -Wrap
